def gen(rng):
    def fmt(m):
        return f'{len(m)} {len(m[0])}\n' + '\n'.join(' '.join(map(str, row)) for row in m)

    def rnd(r, c, hi):
        return [sorted(rng.randint(1, hi) for _ in range(c)) for _ in range(r)]

    tests = [
        fmt([[7]]),
        fmt([[1, 2, 3]]),
        fmt([[3], [1], [2]]),
        fmt([[5, 5, 5], [5, 5, 5], [5, 5, 5]]),
        fmt([[1, 3, 5], [2, 6, 8], [3, 6, 9]]),
        fmt([[1, 1000000, 1000000], [1, 1, 1000000], [1, 1000000, 1000000]]),
    ]
    shapes = [(1, 5), (5, 1), (3, 3), (3, 5), (5, 3), (1, 9), (9, 1), (7, 3), (3, 7), (5, 5), (1, 1), (1, 3)]
    for r, c in shapes:
        for hi in (3, 20, 1000):
            tests.append(fmt(rnd(r, c, hi)))
    tests.append(fmt(rnd(499, 499, 10 ** 6)))
    tests.append(fmt(rnd(499, 499, 10)))
    tests.append(fmt(rnd(1, 499, 10 ** 6)))
    tests.append(fmt(rnd(499, 1, 10 ** 6)))
    tests.append(fmt(rnd(333, 375, 10 ** 6)))
    return tests

